void Solver::bump_var(int var, double coeff) {
    // increase activity of the variable
    double inc = var_inc * coeff;
    activity[var] += inc;

    // prevent overflow by rescaling all activities and the increment factor
    const double ACT_LIMIT = 1e100;
    if (activity[var] > ACT_LIMIT) {
        const double SCALE = 1e-100;
        for (int i = 1; i <= vars; ++i) activity[i] *= SCALE;
        var_inc *= SCALE;
    }

    // keep the VSIDS heap consistent
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}

